<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {ChatDotRound,Collection,Service,Location,DataLine,SwitchButton,Promotion,Plus,Document,ArrowRight} from '@element-plus/icons-vue'
import {api} from './api'
import Discovery from './Discovery.vue'
import PublicResults from './PublicResults.vue'
import {useSession} from './stores/session'
const session=useSession(),route=useRoute(),router=useRouter()
const page=computed(()=>route.params.page||'chat')
const mode=ref('demo'),login=ref({username:'user',password:''}),busy=ref(false),error=ref('')
const provider=ref(''),retrieval=ref('keyword')
const modeLabel=computed(()=>mode.value==='demo'?'本地业务演示 · 无大模型':(provider.value==='deepseek'?'DeepSeek':'百炼')+' · '+(retrieval.value==='hybrid'?'混合向量检索':'BM25 关键词检索'))
const messages=ref([]),conversations=ref([]),conversationId=ref(null),input=ref('')
const latestPublicSearch=computed(()=>messages.value.findLast(m=>m.extra?.publicSearch)?.extra.publicSearch.searchId)
const camps=ref([]),tickets=ref([]),documents=ref([]),metrics=ref(null)
const detail=ref(null),detailOpen=ref(false),citation=ref(null),citationOpen=ref(false)
const reply=ref(''),nextStatus=ref('处理中'),upload=ref({campsiteId:'c01',title:'',category:'营地规则',visibility:'PUBLIC',documentId:''}),file=ref(null),uploadOpen=ref(false)
const docDetail=ref(null),docOpen=ref(false),editCamp=ref(null),campOpen=ref(false),confirmed=ref(new Set())
let actionVersion=0,conversationVersion=0
const roleName=computed(()=>({USER:'露营体验者',STAFF:'客服人员',OPS:'知识运营'})[session.user?.role]||'')
const allNav=[
 {id:'chat',label:'营地助手',icon:ChatDotRound,roles:['USER','STAFF','OPS']},
 {id:'discovery',label:'找真实营地',icon:Location,roles:['USER','STAFF','OPS']},
 {id:'tickets',label:'我的工单',icon:Collection,roles:['USER','STAFF','OPS']},
 {id:'staff',label:'客服工作台',icon:Service,roles:['STAFF']},
 {id:'knowledge',label:'知识资料',icon:Document,roles:['OPS']},
 {id:'campsites',label:'营地管理',icon:Location,roles:['OPS']},
 {id:'metrics',label:'运行概览',icon:DataLine,roles:['OPS']}
]
const nav=computed(()=>allNav.filter(n=>n.roles.includes(session.user?.role)))
const currentNav=computed(()=>nav.value.find(n=>n.id===page.value)||nav.value[0])
const suggestions=['帮我找杭州的真实露营地','青岚竹溪营地可以带宠物吗？','云汀湖畔营地怎么取消？','投诉青岚竹溪营地：停车区域标识不清晰，请帮我整理工单']
async function run(task){const version=++actionVersion;error.value='';busy.value=true;try{return await task()}catch(e){if(version===actionVersion&&e.name!=='AbortError'){error.value=e.message;ElMessage.error(e.message)}}finally{if(version===actionVersion)busy.value=false}}
async function enter(){await run(async()=>{await session.login(login.value.username,login.value.password);login.value.password='';await refresh();router.replace('/chat')})}
async function refresh(){camps.value=await api('/campsites');conversations.value=await api('/conversations')}
function navigate(id){if(page.value===id)return loadPage(id);router.push('/'+id)}
async function loadPage(id){await run(async()=>{if(id==='tickets')tickets.value=await api('/tickets');if(id==='staff')tickets.value=await api('/staff/tickets');if(id==='knowledge')documents.value=await api('/ops/documents');if(id==='metrics')metrics.value=await api('/ops/metrics');if(id==='campsites')camps.value=await api('/ops/campsites')})}
watch(page,id=>{if(session.user&&nav.value.some(n=>n.id===id))loadPage(id)})
watch(()=>session.user?.id,()=>{actionVersion++;conversationVersion++;busy.value=false;conversationId.value=null;messages.value=[];tickets.value=[];conversations.value=[];camps.value=[];documents.value=[];metrics.value=null;confirmed.value=new Set();detail.value=null;docDetail.value=null;citation.value=null;editCamp.value=null;file.value=null;detailOpen.value=false;docOpen.value=false;citationOpen.value=false;campOpen.value=false;uploadOpen.value=false;upload.value={campsiteId:'c01',title:'',category:'营地规则',visibility:'PUBLIC',documentId:''};input.value='';reply.value='';error.value=''},{flush:'sync'})
async function selectConversation(id){const version=++conversationVersion;await run(async()=>{conversationId.value=id;const rows=await api('/conversations/'+id+'/messages');if(version!==conversationVersion)return;messages.value=rows;router.push('/chat')})}
function focusMain(){document.getElementById('main')?.focus()}
function newConversation(){conversationVersion++;conversationId.value=null;messages.value=[];input.value='';router.push('/chat')}
async function send(text){const message=(text||input.value).trim();if(!message||busy.value)return;const version=conversationVersion;input.value='';messages.value.push({id:crypto.randomUUID(),role:'user',content:message,extra:{}});await run(async()=>{const result=await api('/chat',{method:'POST',body:{message,conversationId:conversationId.value}});if(version!==conversationVersion)return;conversationId.value=result.conversationId;messages.value.push({id:result.requestId,role:'assistant',content:result.answer,extra:result});conversations.value=await api('/conversations')})}
async function confirm(draft){await run(async()=>{const ticket=await api('/ticket-drafts/'+draft.id+'/confirm',{method:'POST'});confirmed.value.add(draft.id);ElMessage.success('工单已提交：'+ticket.id.slice(0,8))})}
async function showCitation(c){await run(async()=>{citation.value=await api('/knowledge/citations/'+c.id);citationOpen.value=true})}
async function showTicket(t){await run(async()=>{detail.value=await api((page.value==='staff'?'/staff':'')+'/tickets/'+t.id);nextStatus.value=t.status==='待处理'?'处理中':'已解决';reply.value='';detailOpen.value=true})}
async function handleTicket(){await run(async()=>{detail.value=await api('/staff/tickets/'+detail.value.id,{method:'PATCH',body:{status:nextStatus.value,reply:reply.value,revision:detail.value.revision}});tickets.value=await api('/staff/tickets');nextStatus.value=detail.value.status==='待处理'?'处理中':'已解决';reply.value='';ElMessage.success('处理记录已保存')})}
async function viewDocument(d){await run(async()=>{docDetail.value=await api('/ops/documents/'+d.id);docOpen.value=true})}
function newUpload(d){upload.value={campsiteId:d?.campsite_id||'c01',title:d?.title||'',category:d?.category||'营地规则',visibility:d?.visibility||'PUBLIC',documentId:d?.id||''};file.value=null;uploadOpen.value=true}
async function uploadFile(){if(!file.value){error.value='请选择资料文件';return}await run(async()=>{const body=new FormData();Object.entries(upload.value).forEach(([k,v])=>body.append(k,v));body.append('file',file.value);await api('/ops/documents',{method:'POST',body});uploadOpen.value=false;documents.value=await api('/ops/documents');ElMessage.success('已加入解析队列，请刷新查看状态')})}
async function publish(version){await run(async()=>{await api('/ops/documents/'+docDetail.value.id+'/publish',{method:'POST',body:{versionId:version.id}});docDetail.value=await api('/ops/documents/'+docDetail.value.id);documents.value=await api('/ops/documents');ElMessage.success('版本已发布')})}
async function unpublish(d){await run(async()=>{await api('/ops/documents/'+d.id+'/unpublish',{method:'POST'});documents.value=await api('/ops/documents');ElMessage.success('资料已下架')})}
function openCamp(c){editCamp.value=c?{...c,feeDesc:c.fee_desc}:{name:'',city:'',terrain:'草地',facilities:'',feeDesc:'',description:''};campOpen.value=true}
async function saveCamp(){await run(async()=>{const c=editCamp.value;await api('/ops/campsites'+(c.id?'/'+c.id:''),{method:c.id?'PUT':'POST',body:c});camps.value=await api('/ops/campsites');campOpen.value=false;ElMessage.success('营地信息已保存')})}
onMounted(async()=>{window.addEventListener('camp-unauthorized',()=>session.logout());await run(async()=>{const health=await api('/health');mode.value=health.mode;provider.value=health.chatProvider;retrieval.value=health.retrievalMode;await session.load();if(session.user){await refresh();await loadPage(page.value)}})})
</script>

<template>
  <a class="skip-link" href="#main" @click.prevent="focusMain">跳转到主要内容</a>
  <div v-if="!session.user" class="login-shell">
    <section class="login-story"><div class="wordmark">营知<span>CAMP AGENT</span></div><span class="eyebrow">A LITTLE CLOSER TO NATURE</span><h1>把问题留给营知，<br>把时间留给自然。</h1><p>从营地选择到服务咨询，依据资料回答，<br>让每一次沟通都有来源、每一项服务都有进度。</p><div class="landscape" aria-hidden="true"><div></div><div></div><div></div></div><small>虚构营地 · 演示资料 · 可追溯服务</small></section>
    <main id="main" tabindex="-1" class="login-card"><span class="eyebrow">WELCOME TO CAMP AGENT</span><h2>欢迎回来</h2><p>登录你的营地服务工作空间</p><el-form label-position="top" @submit.prevent="enter"><el-form-item label="账号"><el-input v-model="login.username" autocomplete="username" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="login.password" type="password" show-password autocomplete="current-password" size="large"/></el-form-item><p v-if="error" class="error" role="alert">{{error}}</p><el-button native-type="submit" type="primary" size="large" :loading="busy" class="full">进入工作空间 <el-icon><ArrowRight/></el-icon></el-button></el-form><div class="demo-accounts"><p>演示角色</p><button v-for="a in ['user','staff','ops','user2']" :key="a" @click="login.username=a">{{a}}</button><small>本地初始密码见 README；云端密码由部署者设置。</small></div><div class="mode-note">{{modeLabel}}</div></main>
  </div>
  <div v-else class="workspace">
    <aside class="sidebar"><div class="wordmark">营知<span>CAMP AGENT</span></div><div class="workspace-label">营地咨询与服务</div><nav aria-label="主要导航"><button v-for="n in nav" :key="n.id" :class="{active:page===n.id}" @click="navigate(n.id)"><el-icon><component :is="n.icon"/></el-icon>{{n.label}}<span v-if="page===n.id" class="nav-dot"></span></button></nav><section v-if="page==='chat'" class="history"><div class="section-label">最近会话<button aria-label="新建会话" @click="newConversation"><el-icon><Plus/></el-icon></button></div><button v-for="c in conversations" :key="c.id" :class="{chosen:c.id===conversationId}" @click="selectConversation(c.id)">{{c.title}}</button></section><div class="sidebar-bottom"><div class="avatar">{{session.user.name?.slice(-1)}}</div><div><strong>{{session.user.name}}</strong><small>{{roleName}}</small></div><button aria-label="退出登录" @click="session.logout"><el-icon><SwitchButton/></el-icon></button></div></aside>
    <main id="main" tabindex="-1" class="main"><header><div><span class="breadcrumb">工作空间 / {{currentNav?.label}}</span><h1>{{currentNav?.label}}</h1></div><el-tag :type="mode==='demo'?'warning':'success'" effect="plain">{{modeLabel}}</el-tag><el-button aria-label="退出登录" link @click="session.logout">退出</el-button></header><p v-if="error" class="error top-error" role="alert">{{error}}</p>
    <div v-if="!nav.some(n=>n.id===page)" class="empty">该工作区不对当前角色开放。</div>
    <template v-else-if="page==='chat'"><div class="chat-layout"><section class="conversation"><div v-if="!messages.length" class="welcome"><span class="welcome-symbol"><el-icon><ChatDotRound/></el-icon></span><span class="eyebrow">YOUR CAMPING COMPANION</span><h2>下一次露营，从这里出发。</h2><p>告诉我你的想法，一起找到合适的营地、核实规则，<br>或跟进需要帮助的事情。</p><div class="suggestions"><button v-for="(s,i) in suggestions" :key="s" :disabled="busy" @click="send(s)"><span>0{{i+1}}</span>{{s}}<el-icon><ArrowRight/></el-icon></button></div></div><article v-for="m in messages" :key="m.id" class="message" :class="m.role"><div class="message-label">{{m.role==='user'?'你':'营知助手'}}<small v-if="m.extra?.mode==='demo'"> · 业务演示</small></div><div class="message-content">{{m.content}}</div><PublicResults :result="m.extra" :active="m.extra?.publicSearch?.searchId===latestPublicSearch" :busy="busy" @select="position=>send('查看第'+position+'个真实营地详情')" /><div v-if="m.extra?.toolSummary?.length" class="tool-summary"><el-tag v-for="(t,i) in m.extra.toolSummary" :key="i" size="small" type="info">{{t.name}} {{t.count!==undefined?'· '+t.count+' 条':''}}</el-tag></div><div v-if="m.extra?.citations?.length" class="source-list"><span>回答依据</span><button v-for="c in m.extra.citations" :key="c.id" @click="showCitation(c)"><el-icon><Document/></el-icon>{{c.title}} · {{c.location}}</button></div><div v-if="m.extra?.pendingTicketDraft" class="draft-card"><span class="eyebrow">待确认服务工单</span><h3>{{m.extra.pendingTicketDraft.title}}</h3><p>{{m.extra.pendingTicketDraft.description}}</p><el-tag>{{m.extra.pendingTicketDraft.kind}}</el-tag><el-button type="primary" :loading="busy" :disabled="confirmed.has(m.extra.pendingTicketDraft.id)" @click="confirm(m.extra.pendingTicketDraft)">{{confirmed.has(m.extra.pendingTicketDraft.id)?'已提交':'确认并提交工单'}}</el-button></div></article><div v-if="busy" class="processing" role="status">正在查询与处理，请稍候…</div><form class="composer" @submit.prevent="send()"><label for="question" class="sr-only">向营知提问</label><textarea id="question" v-model="input" rows="2" maxlength="2000" placeholder="输入营地、规则或你需要帮助的事情…" @keydown.enter.exact.prevent="send()"></textarea><div><span>真实地点标注地图来源，演示资料单独说明。服务提交前需确认。</span><el-button type="primary" native-type="submit" :disabled="!input.trim()" :loading="busy"><el-icon><Promotion/></el-icon>发送</el-button></div></form></section><aside class="context-panel"><span class="eyebrow">CAMP DIRECTORY</span><h3>认识这些营地</h3><p>5 个虚构营地，12 类业务资料。点击名称继续咨询。</p><button v-for="c in camps" :key="c.id" class="camp-card" @click="input=c.name+'的预订规则是什么？'"><span>{{c.terrain}}</span><h4>{{c.name}}</h4><p>{{c.city}} · {{c.facilities}}</p><small>{{c.fee_desc}}</small></button><div class="trust-note"><strong>每条回答，都有依据。</strong><p>查看引用原文，核对资料版本；信息不足时会明确说明。</p></div></aside></div></template>
    <Discovery v-else-if="page==='discovery'" />
    <section v-else-if="page==='tickets'||page==='staff'" class="panel"><div class="panel-heading"><div><h2>{{page==='staff'?'服务处理队列':'我的服务记录'}}</h2><p>从提交到回复，保留每一步进度。</p></div><el-button @click="navigate(page)">刷新列表</el-button></div><el-table :data="tickets" empty-text="暂时没有工单"><el-table-column prop="title" label="问题" min-width="220"/><el-table-column prop="campsite_name" label="营地" min-width="150"/><el-table-column prop="kind" label="类别" width="90"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="showTicket(row)">查看详情</el-button></template></el-table-column></el-table></section>
    <section v-else-if="page==='knowledge'" class="panel"><div class="panel-heading"><div><h2>知识资料库</h2><p>解析预览 → 人工核对 → 发布生效。内部资料仅向工作人员开放。</p></div><div><el-button @click="navigate('knowledge')">刷新状态</el-button><el-button type="primary" @click="newUpload()">上传资料</el-button></div></div><el-table :data="documents"><el-table-column prop="title" label="资料" min-width="230"/><el-table-column prop="category" label="类别" width="120"/><el-table-column prop="visibility" label="范围" width="100"/><el-table-column label="状态" min-width="110"><template #default="{row}"><el-tag :type="row.status==='FAILED'?'danger':'info'">{{row.current_version===row.version_id?'当前已发布':row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="viewDocument(row)">预览</el-button><el-button link type="primary" @click="newUpload(row)">新版本</el-button><el-button v-if="row.current_version" link type="danger" @click="unpublish(row)">下架</el-button></template></el-table-column></el-table></section>
    <section v-else-if="page==='campsites'" class="panel"><div class="panel-heading"><div><h2>营地信息</h2><p>维护当前业务事实，助手下次查询即读取最新内容。</p></div><el-button type="primary" @click="openCamp()">新增营地</el-button></div><el-table :data="camps"><el-table-column prop="name" label="名称" min-width="170"/><el-table-column prop="city" label="城市" width="100"/><el-table-column prop="facilities" label="设施" min-width="190"/><el-table-column prop="fee_desc" label="收费说明" min-width="230"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openCamp(row)">编辑</el-button></template></el-table-column></el-table></section>
    <section v-else-if="page==='metrics'" class="panel"><div class="panel-heading"><div><h2>运行概览</h2><p>本地演示与真实模型请求分别统计，不代表已通过效果验收。</p></div><el-button @click="navigate('metrics')">刷新</el-button></div><template v-if="metrics"><h3>请求与平均耗时</h3><el-table :data="metrics.requests"><el-table-column prop="mode" label="模式"/><el-table-column prop="status" label="结果"/><el-table-column prop="total" label="请求数"/><el-table-column prop="avg_ms" label="平均毫秒"/></el-table><h3>工单分布</h3><el-table :data="metrics.tickets"><el-table-column prop="status" label="状态"/><el-table-column prop="total" label="数量"/></el-table><h3>文档版本</h3><el-table :data="metrics.documents"><el-table-column prop="status" label="状态"/><el-table-column prop="total" label="数量"/></el-table></template></section>
    </main>
    <el-dialog v-model="citationOpen" title="引用原文" width="min(720px, 94vw)"><template v-if="citation"><h3>{{citation.title}}</h3><el-tag v-if="citation.historical" type="warning">历史版本：已更新或下架</el-tag><p>版本 {{citation.version_id}} · {{citation.location}}</p><pre class="preview-text">{{citation.content}}</pre></template></el-dialog>
    <el-dialog v-model="detailOpen" title="工单详情与进度" width="min(700px, 94vw)"><template v-if="detail"><h3>{{detail.title}}</h3><p class="preview-text">{{detail.description}}</p><el-tag>{{detail.status}}</el-tag><p class="subtle">工单编号：{{detail.id}}</p><el-timeline><el-timeline-item v-for="(e,i) in detail.events" :key="i" :timestamp="e.created_at">{{e.status}} · {{e.reply}}</el-timeline-item></el-timeline><el-form v-if="page==='staff'&&!['已解决','已关闭'].includes(detail.status)" label-position="top"><el-form-item label="下一状态"><el-select v-model="nextStatus"><el-option v-for="s in detail.status==='待处理'?['处理中']:['已解决','已关闭']" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="公开回复 / 处理说明"><el-input v-model="reply" type="textarea" :rows="4" maxlength="3000"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!reply.trim()" @click="handleTicket">保存处理记录</el-button></el-form></template></el-dialog>
    <el-dialog v-model="uploadOpen" title="上传知识资料" width="min(640px, 94vw)"><el-form label-position="top"><el-form-item label="营地"><el-select v-model="upload.campsiteId" :disabled="!!upload.documentId"><el-option v-for="c in camps" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="upload.title" maxlength="200"/></el-form-item><el-form-item label="类别"><el-input v-model="upload.category" maxlength="80"/></el-form-item><el-form-item label="访问范围"><el-select v-model="upload.visibility" :disabled="!!upload.documentId"><el-option label="公开资料" value="PUBLIC"/><el-option label="内部客服资料" value="STAFF"/></el-select></el-form-item><el-form-item label="文件（不超过 10MB）"><input type="file" accept=".md,.txt,.pdf,.docx,.png,.jpg,.jpeg" aria-label="选择知识文件" @change="file=$event.target.files[0]"></el-form-item><p class="subtle">图片和扫描 PDF 的 OCR 需要云模型配置。上传完成后请刷新状态并检查提取原文。</p><el-button type="primary" :loading="busy" :disabled="!upload.title.trim()||!file" @click="uploadFile">上传并解析</el-button></el-form></el-dialog>
    <el-dialog v-model="docOpen" title="资料版本与解析预览" width="min(850px, 94vw)"><template v-if="docDetail"><h3>{{docDetail.title}}</h3><section v-for="v in docDetail.versions" :key="v.id" class="version"><p>{{v.filename}} <el-tag>{{v.status}}</el-tag></p><p v-if="v.error_message" class="error">{{v.error_message}}</p><pre class="preview-text">{{v.extracted_text||'尚未提取到文本'}}</pre><el-button v-if="['REVIEW','PUBLISHED'].includes(v.status)&&docDetail.current_version!==v.id" type="primary" :loading="busy" @click="publish(v)">已核对原文，发布此版本</el-button></section></template></el-dialog>
    <el-dialog v-model="campOpen" title="维护营地信息" width="min(640px, 94vw)"><el-form v-if="editCamp" label-position="top"><el-form-item v-for="[k,label] in [['name','名称'],['city','城市'],['terrain','类型'],['facilities','设施（逗号分隔）'],['feeDesc','收费说明'],['description','介绍']]" :key="k" :label="label"><el-input v-model="editCamp[k]" :type="k==='description'?'textarea':'text'"/></el-form-item><el-button type="primary" :loading="busy" @click="saveCamp">保存营地</el-button></el-form></el-dialog>
  </div>
</template>


